insert into public.app_translations (translation_key,screen_key,module_name,text_type,ar_text,en_text,default_ar,default_en,is_active,updated_at)
select translation_key,screen_key,module_name,text_type,ar_text,en_text,default_ar,default_en,is_active,updated_at
from translation_seed
on conflict (translation_key) do update set
  screen_key=excluded.screen_key,
  module_name=excluded.module_name,
  text_type=excluded.text_type,
  ar_text=case
    when nullif(btrim(public.app_translations.ar_text),'') is null then excluded.ar_text
    when excluded.translation_key='customers.col.code' and lower(btrim(public.app_translations.ar_text))='code' then excluded.ar_text
    when excluded.translation_key='customers.col.name' and lower(btrim(public.app_translations.ar_text))='name' then excluded.ar_text
    when excluded.translation_key='customers.col.address' and lower(btrim(public.app_translations.ar_text))='address' then excluded.ar_text
    when excluded.translation_key='customers.col.mobile' and lower(btrim(public.app_translations.ar_text))='mobile' then excluded.ar_text
    else public.app_translations.ar_text
  end,
  en_text=case when nullif(btrim(public.app_translations.en_text),'') is null then excluded.en_text else public.app_translations.en_text end,
  default_ar=excluded.default_ar,
  default_en=excluded.default_en,
  is_active=true,
  updated_at=now();

commit;
